def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    fill = counts.most_common(1)[0][0]

    # Find the repeated, nearly uniform horizontal and vertical grid lines.
    def line_coords(lines, length):
        result = []
        for i, line in enumerate(lines):
            color, n = Counter(line).most_common(1)[0]
            if color != fill and n >= length - 2:
                result.append((i, color))
        return result

    horizontal = line_coords(grid, w)
    vertical = line_coords(
        [[grid[r][c] for r in range(h)] for c in range(w)], h
    )
    if len(horizontal) < 2 or len(vertical) < 2:
        return [[fill]]

    line_color = Counter(c for _, c in horizontal + vertical).most_common(1)[0][0]
    nr, nc = len(horizontal) - 1, len(vertical) - 1
    out = [[fill for _ in range(nc)] for _ in range(nr)]

    # Keep the upper-left crossing of a repeated marker pattern.
    for i in range(nr):
        for j in range(nc):
            r, c = horizontal[i][0], vertical[j][0]
            value = grid[r][c]
            if value == line_color or value == fill:
                continue
            down = grid[horizontal[i + 1][0]][c] == value
            right = grid[r][vertical[j + 1][0]] == value
            if down or right:
                out[i][j] = value

    # Crop unused outer rows/columns.
    while len(out) > 1 and all(v == fill for v in out[0]):
        out.pop(0)
    while len(out) > 1 and all(v == fill for v in out[-1]):
        out.pop()
    while len(out[0]) > 1 and all(row[0] == fill for row in out):
        for row in out:
            row.pop(0)
    while len(out[0]) > 1 and all(row[-1] == fill for row in out):
